{
  "name": "Newport ESP301 多轴电机运动控制器",
  "name_en": "Newport ESP301 Multi-Axis Motor Controller",
  "manufacturer": "Newport",
  "description": "用于驱动和协调多轴电动位移台、线性/旋转平台及执行器的实验室运动控制器。它支持回零、位置与速度控制、限位管理以及伺服参数整定，常用于光学对准、样品定位、自动扫描和精密运动实验。",
  "description_en": "A laboratory multi-axis motion controller used to drive and coordinate motorized stages, linear or rotary stages, and actuators. It supports homing, position and velocity control, limit handling, and servo tuning, and is commonly used for optical alignment, sample positioning, automated scanning, and precision motion experiments.",
  "tag_hints": [
    "multi-axis motion control",
    "motorized stage control",
    "precision positioning",
    "homing and limit switches",
    "servo tuning",
    "optical alignment",
    "automated scanning"
  ],
  "actions": [
    {
      "action_name": "auto-define_program",
      "description": "定义并保存用户程序",
      "description_en": "Define and store a user program."
    },
    {
      "action_name": "auto-execute_bulk_command",
      "description": "批量执行多条控制命令",
      "description_en": "Execute multiple control commands in a batch."
    },
    {
      "action_name": "auto-reset",
      "description": "复位运动控制器",
      "description_en": "Reset the motion controller."
    },
    {
      "action_name": "auto-run_program",
      "description": "运行已保存的用户程序",
      "description_en": "Run a previously stored user program."
    },
    {
      "action_name": "auto-search_for_home",
      "description": "使指定轴执行回零搜索",
      "description_en": "Search for the home position of a specified axis."
    },
    {
      "action_name": "auto-axis",
      "description": "获取轴列表",
      "description_en": "Get the available axes."
    },
    {
      "action_name": "auto-axis_id",
      "description": "获取轴编号",
      "description_en": "Get the axis identifier."
    },
    {
      "action_name": "auto-is_motion_done",
      "description": "获取运动是否完成",
      "description_en": "Get whether motion is complete."
    },
    {
      "action_name": "auto-acceleration",
      "description": "获取/设置加速度",
      "description_en": "Get/set acceleration."
    },
    {
      "action_name": "auto-deceleration",
      "description": "获取/设置减速度",
      "description_en": "Get/set deceleration."
    },
    {
      "action_name": "auto-estop_deceleration",
      "description": "获取/设置急停减速度",
      "description_en": "Get/set emergency-stop deceleration."
    },
    {
      "action_name": "auto-jerk",
      "description": "获取/设置加加速度",
      "description_en": "Get/set jerk."
    },
    {
      "action_name": "auto-velocity",
      "description": "获取/设置速度",
      "description_en": "Get/set velocity."
    },
    {
      "action_name": "auto-max_velocity",
      "description": "获取/设置最大速度",
      "description_en": "Get/set maximum velocity."
    },
    {
      "action_name": "auto-max_base_velocity",
      "description": "获取/设置最大基准速度",
      "description_en": "Get/set maximum base velocity."
    },
    {
      "action_name": "auto-jog_high_velocity",
      "description": "获取/设置点动高速速度",
      "description_en": "Get/set jog high velocity."
    },
    {
      "action_name": "auto-jog_low_velocity",
      "description": "获取/设置点动低速速度",
      "description_en": "Get/set jog low velocity."
    },
    {
      "action_name": "auto-homing_velocity",
      "description": "获取/设置回零速度",
      "description_en": "Get/set homing velocity."
    },
    {
      "action_name": "auto-max_acceleration",
      "description": "获取/设置最大加速度",
      "description_en": "Get/set maximum acceleration."
    },
    {
      "action_name": "auto-max_deceleration",
      "description": "获取/设置最大减速度",
      "description_en": "Get/set maximum deceleration."
    },
    {
      "action_name": "auto-position",
      "description": "获取/设置位置",
      "description_en": "Get/set position."
    },
    {
      "action_name": "auto-desired_position",
      "description": "获取/设置目标位置",
      "description_en": "Get/set desired position."
    },
    {
      "action_name": "auto-desired_velocity",
      "description": "获取/设置目标速度",
      "description_en": "Get/set desired velocity."
    },
    {
      "action_name": "auto-home",
      "description": "获取/设置原点位置",
      "description_en": "Get/set home position."
    },
    {
      "action_name": "auto-units",
      "description": "获取/设置运动单位",
      "description_en": "Get/set motion units."
    },
    {
      "action_name": "auto-encoder_resolution",
      "description": "获取/设置编码器分辨率",
      "description_en": "Get/set encoder resolution."
    },
    {
      "action_name": "auto-full_step_resolution",
      "description": "获取/设置整步分辨率",
      "description_en": "Get/set full-step resolution."
    },
    {
      "action_name": "auto-left_limit",
      "description": "获取/设置左侧软件限位",
      "description_en": "Get/set left software limit."
    },
    {
      "action_name": "auto-right_limit",
      "description": "获取/设置右侧软件限位",
      "description_en": "Get/set right software limit."
    },
    {
      "action_name": "auto-error_threshold",
      "description": "获取/设置误差阈值",
      "description_en": "Get/set error threshold."
    },
    {
      "action_name": "auto-current",
      "description": "获取/设置电机电流",
      "description_en": "Get/set motor current."
    },
    {
      "action_name": "auto-voltage",
      "description": "获取/设置电机电压",
      "description_en": "Get/set motor voltage."
    },
    {
      "action_name": "auto-motor_type",
      "description": "获取/设置电机类型",
      "description_en": "Get/set motor type."
    },
    {
      "action_name": "auto-feedback_configuration",
      "description": "获取/设置反馈配置",
      "description_en": "Get/set feedback configuration."
    },
    {
      "action_name": "auto-position_display_resolution",
      "description": "获取/设置位置显示分辨率",
      "description_en": "Get/set position display resolution."
    },
    {
      "action_name": "auto-trajectory",
      "description": "获取/设置轨迹参数",
      "description_en": "Get/set trajectory settings."
    },
    {
      "action_name": "auto-microstep_factor",
      "description": "获取/设置细分因子",
      "description_en": "Get/set microstep factor."
    },
    {
      "action_name": "auto-hardware_limit_configuration",
      "description": "获取/设置硬件限位配置",
      "description_en": "Get/set hardware limit configuration."
    },
    {
      "action_name": "auto-acceleration_feed_forward",
      "description": "获取/设置加速度前馈",
      "description_en": "Get/set acceleration feed-forward."
    },
    {
      "action_name": "auto-proportional_gain",
      "description": "获取/设置比例增益",
      "description_en": "Get/set proportional gain."
    },
    {
      "action_name": "auto-derivative_gain",
      "description": "获取/设置微分增益",
      "description_en": "Get/set derivative gain."
    },
    {
      "action_name": "auto-integral_gain",
      "description": "获取/设置积分增益",
      "description_en": "Get/set integral gain."
    },
    {
      "action_name": "auto-integral_saturation_gain",
      "description": "获取/设置积分饱和增益",
      "description_en": "Get/set integral saturation gain."
    },
    {
      "action_name": "auto-encoder_position",
      "description": "获取/设置编码器位置",
      "description_en": "Get/set encoder position."
    },
    {
      "action_name": "auto-move",
      "description": "移动指定轴",
      "description_en": "Move the axis."
    },
    {
      "action_name": "auto-move_to_hardware_limit",
      "description": "使轴移动到硬件限位",
      "description_en": "Move the axis to a hardware limit."
    },
    {
      "action_name": "auto-move_indefinitely",
      "description": "使轴连续运动直至停止",
      "description_en": "Move the axis continuously until stopped."
    },
    {
      "action_name": "auto-abort_motion",
      "description": "立即中止当前运动",
      "description_en": "Abort the current motion immediately."
    },
    {
      "action_name": "auto-wait_for_stop",
      "description": "等待轴停止",
      "description_en": "Wait for the axis to stop."
    },
    {
      "action_name": "auto-stop_motion",
      "description": "停止轴运动",
      "description_en": "Stop axis motion."
    },
    {
      "action_name": "auto-wait_for_position",
      "description": "等待轴到达指定位置",
      "description_en": "Wait for the axis to reach a target position."
    },
    {
      "action_name": "auto-wait_for_motion",
      "description": "等待轴运动完成",
      "description_en": "Wait for axis motion to complete."
    },
    {
      "action_name": "auto-enable",
      "description": "启用轴驱动",
      "description_en": "Enable the axis drive."
    },
    {
      "action_name": "auto-disable",
      "description": "禁用轴驱动",
      "description_en": "Disable the axis drive."
    },
    {
      "action_name": "auto-setup_axis",
      "description": "配置轴参数",
      "description_en": "Configure axis settings."
    },
    {
      "action_name": "auto-read_setup",
      "description": "读取轴设置",
      "description_en": "Read axis settings."
    },
    {
      "action_name": "auto-get_status",
      "description": "获取状态",
      "description_en": "Get status."
    }
  ]
}

